class Solution {
    std::unordered_map<std::string, std::string> parent;
    std::unordered_map<std::string, double> weight;

    std::pair<std::string, double> find(const std::string& x) {
        if (!parent.count(x)) {
            parent[x] = x;
            weight[x] = 1.0;
            return {x, 1.0};
        }
        if (parent[x] != x) {
            auto [p, w] = find(parent[x]);
            parent[x] = p;
            weight[x] *= w;
        }
        return {parent[x], weight[x]};
    }
public:
    bool checkContradictions(std::vector<std::vector<std::string>>& equations, std::vector<double>& values) {
        for (size_t i = 0; i < equations.size(); ++i) {
            const auto& a = equations[i][0];
            const auto& b = equations[i][1];
            double val = values[i];
            auto [ra, wa] = find(a);
            auto [rb, wb] = find(b);
            if (ra == rb) {
                if (std::abs(wa / wb - val) > 1e-5) return true;
            } else {
                parent[ra] = rb;
                weight[ra] = val * wb / wa;
            }
        }
        return false;
    }
};

class Solution {
    private java.util.Map<String, String> parent = new java.util.HashMap<>();
    private java.util.Map<String, Double> weight = new java.util.HashMap<>();

    private Object[] find(String x) {
        if (!parent.containsKey(x)) {
            parent.put(x, x);
            weight.put(x, 1.0);
            return new Object[]{x, 1.0};
        }
        if (!parent.get(x).equals(x)) {
            Object[] res = find(parent.get(x));
            parent.put(x, (String) res[0]);
            weight.put(x, weight.get(x) * (Double) res[1]);
        }
        return new Object[]{parent.get(x), weight.get(x)};
    }

    public boolean checkContradictions(java.util.List<java.util.List<String>> equations, double[] values) {
        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0);
            String b = equations.get(i).get(1);
            double val = values[i];
            Object[] resA = find(a);
            Object[] resB = find(b);
            String ra = (String) resA[0];
            double wa = (Double) resA[1];
            String rb = (String) resB[0];
            double wb = (Double) resB[1];
            if (ra.equals(rb)) {
                if (Math.abs(wa / wb - val) > 1e-5) return true;
            } else {
                parent.put(ra, rb);
                weight.put(ra, val * wb / wa);
            }
        }
        return false;
    }
}

var checkContradictions = function(equations, values) {
    const parent = new Map();
    const weight = new Map();
    const find = (x) => {
        if (!parent.has(x)) {
            parent.set(x, x);
            weight.set(x, 1.0);
            return [x, 1.0];
        }
        if (parent.get(x) !== x) {
            const [p, w] = find(parent.get(x));
            parent.set(x, p);
            weight.set(x, weight.get(x) * w);
        }
        return [parent.get(x), weight.get(x)];
    };
    for (let i = 0; i < equations.length; i++) {
        const [a, b] = equations[i];
        const val = values[i];
        const [ra, wa] = find(a);
        const [rb, wb] = find(b);
        if (ra === rb) {
            if (Math.abs(wa / wb - val) > 1e-5) return true;
        } else {
            parent.set(ra, rb);
            weight.set(ra, val * wb / wa);
        }
    }
    return false;
};
